#!/usr/bin/env bash
# Compile the Noir circuits and regenerate the Solidity verifiers.
#
# The two files under contracts/src/verifiers/ are machine generated by
# barretenberg and then renamed (HonkVerifier -> {Join,Vote}HonkVerifier) so the
# two can coexist in one Foundry project. They are checked in because
# `forge build` has to work without a Noir toolchain; rerun this script whenever
# a circuit changes, or the on-chain verifier will reject every proof.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
verifiers="$root/contracts/src/verifiers"
mkdir -p "$verifiers"

echo "==> nargo compile"
(cd "$root/circuits" && nargo compile)

generate() {
  local circuit="$1" name="$2" out="$verifiers/$2.sol"
  echo "==> $circuit: verification key"
  bb write_vk --verifier_target evm \
    -b "$root/circuits/target/$circuit.json" \
    -o "$root/circuits/target/$circuit" >/dev/null
  echo "==> $circuit: Solidity verifier -> ${out#$root/}"
  bb write_solidity_verifier --verifier_target evm \
    -k "$root/circuits/target/$circuit/vk" -o "$out" >/dev/null

  # Give each verifier a unique contract name and mark the file as generated.
  sed -i.bak "s/^contract HonkVerifier is/contract ${name}Honk is/" "$out"
  rm -f "$out.bak"
  printf '// GENERATED FILE - do not edit. Produced by scripts/build-circuits.sh\n// Verifier for circuits/%s. Regenerate after any circuit change.\n%s\n' \
    "$circuit" "$(cat "$out")" > "$out.tmp"
  mv "$out.tmp" "$out"
}

generate join JoinVerifier
generate vote VoteVerifier

echo "==> done"
